    begin
        if(rst)
        	begin
        		counter <= 4'd0;
                clk_gen <= 1'b0;
        	end
        else
        	begin
        		if (counter < speedctr_i) 
        		    begin
        		        counter <= counter + 1'b1;
                        clk_gen <= clk_gen;
        		    end
        		else 
        		    begin
    					counter <= 4'b0000;	
                        clk_gen <= ~clk_gen;	        
        		    end
        	end
    end
endmodule

