module top_module(
  input clk_in,
  input rst,
  input [31:0] frequency,
  input [7:0] duty_cycle,
  output reg clk_out
);reg [31:0] period;
  reg [31:0] high_time;
  reg [31:0] low_time;
  reg [1:0] duty_cycle_divider;

  always @ (posedge clk_in or posedge rst) begin
    if (rst) begin
      clk_out <= 0;
      period <= 0;
      high_time <= 0;
      low_time <= 0;
      duty_cycle_divider <= 0;
    end else begin
      period <= clk_in / frequency;
      high_time <= period * duty_cycle / 100;
      low_time <= period - high_time;
      duty_cycle_divider <= period / 256;
      if (duty_cycle_divider == 0) begin
        duty_cycle_divider <= 1;
      end
      if (duty_cycle_divider == 1) begin
        clk_out <= 1;
      end else begin
        if (duty_cycle_divider == 2) begin
          clk_out <= (high_time > low_time);
        end else begin
          clk_out <= (duty_cycle_divider[1] == 1) ? (high_time > low_time) : ~clk_out;
        end
      end
    end
  end

endmodule

