module top_module(
  input wire voltage,
  input wire freq_ref,
  input wire clk, // Added clk input
  output wire freq_out
);reg [31:0] counter;
  reg [31:0] max_count;
  reg [31:0] half_count;
  reg [31:0] freq;

  assign freq_out = freq;

  always @ (voltage or freq_ref) begin
    max_count = (freq_ref == 0) ? 0 : (50000000 / freq_ref); // 50MHz clock
    half_count = (freq_ref == 0) ? 0 : (25000000 / freq_ref); // half the max count
    freq = (voltage * max_count) + half_count;
  end

  always @ (posedge clk) begin
    if (counter == max_count - 1) begin
      counter <= 0;
    end else begin
      counter <= counter + 1;
    end
  end

endmodule

