module top_module(
    input clk,
    input en,
    input wr_en,
    input rS_wr_en,
    input [2:0] rD_sel,
    input [2:0] rS_sel,
    input [15:0] rD_data_in,
    input [15:0] rS_data_in,
    output reg [15:0] rD_data_out,
    output reg [15:0] rS_data_out
);reg [15:0] r0;
reg [15:0] r1;
reg [15:0] rD;

always @(posedge clk) begin
    if (en) begin
        if (rS_wr_en) begin
            case (rS_sel)
                3'b000: r0 <= rS_data_in;
                3'b001: r1 <= rS_data_in;
                default: r0 <= r0;
            endcase
        end
        if (wr_en) begin
            case (rD_sel)
                3'b000: rD <= r0;
                3'b001: rD <= r1;
                default: rD <= rD;
            endcase
        end
    end
end

assign rD_data_out = rD;
assign rS_data_out = (rS_sel == 3'b000) ? r0 : r1;

endmodule

