module top_module(
    input clk_wr,
    input clk_rd,
    input rst,
    input wr_en,
    input rd_en,
    input rp_rst,
    input [8:0] data_in,
    output reg [8:0] data_out, // Change to reg since it is assigned in always block
    output empty,
    output full
);reg [8:0] fifo [0:3];
    reg [1:0] wr_ptr;
    reg [1:0] rd_ptr;
    reg empty_reg;
    reg full_reg;

    always @(posedge clk_wr or posedge rst) begin
        if (rst) begin
            wr_ptr <= 2'b00;
            rd_ptr <= 2'b00;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
            fifo[0] <= 9'b0;
            fifo[1] <= 9'b0;
            fifo[2] <= 9'b0;
            fifo[3] <= 9'b0;
        end else if (wr_en && !full_reg) begin
            fifo[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == 2'b11) begin // This should be 2'b11 for a 2-bit counter (0 to 3)
                wr_ptr <= 2'b00;
            end
            if ((wr_ptr + 1) == rd_ptr) begin // Check if queue is full after increment
                full_reg <= 1'b1;
            end
            empty_reg <= 1'b0;
        end
    end

    always @(posedge clk_rd or posedge rst) begin
        if (rst || rp_rst) begin
            rd_ptr <= 2'b00;
            empty_reg <= 1'b1; // Reset empty flag
            full_reg <= 1'b0;   // Reset full flag
        end else if (rd_en && !empty_reg) begin
            data_out <= fifo[rd_ptr];
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == 2'b11) begin // This should be 2'b11 for a 2-bit counter (0 to 3)
                rd_ptr <= 2'b00;
            end
            if ((rd_ptr + 1) == wr_ptr) begin // Check if queue is empty after increment
                empty_reg <= 1'b1;
            end
            full_reg <= 1'b0;
        end
    end

    assign empty = empty_reg;
    assign full = full_reg;

endmodule

