description:
Design a finite state machine (FSM) that transitions through a series of states: IDLE, SEND, WAIT1, UPDATE1, WAIT2, and UPDATE2, based on the clock signal and an active-low reset. The FSM outputs its current state as a 3-bit signal and includes a mechanism to translate these states into their corresponding string representations for display or debugging purposes. Upon reset, the FSM initializes to the IDLE state, and each state transition occurs synchronously with the clock, enabling sequential operation of the state machine.
module top_module(

           state_r,

           clk, rst_
           );

code:
module top_module(

           state_r,

           clk, rst_
           );parameter [2:0]      
     IDLE                                                       = 3'b000,
     SEND                                                       = 3'b001,
     WAIT1                                                      = 3'b010,
     UPDATE1                                                    = 3'b011,
     WAIT2                                                      = 3'b100;

   parameter [2:0]       UPDATE2  = 3'b101;

   parameter [2:0]      NOT_A_STATE_ELEMENT  = 3'b101;

   parameter [2:0]      
     A_OTHER_STATE_ELEMENT  = 3'b101;



   input        clk; 
   input        rst_;






   output [2:0] state_r; 



   reg [2:0]     state_r; 
   reg [2:0]     state_e1;                



   always @(state_r) begin
      case(state_r) 
        IDLE: begin
           state_e1  = SEND;
        end
        SEND: begin
           state_e1  = WAIT1;
        end
        WAIT1: begin
           state_e1  = UPDATE1;
        end
        UPDATE1: begin
           state_e1  = UPDATE2;
        end
        WAIT2: begin
           state_e1  = UPDATE2;
        end

        UPDATE2: begin
           state_e1  = IDLE;
        end
        default:        state_e1  = state_r;
      endcase
   end

   always @(posedge clk or negedge rst_) begin
      if (~rst_) begin
         state_r <= #0 IDLE;
      end
      else begin
         state_r <= #0 state_e1;
      end
   end





   reg [55:0] _stateascii_r;            
   always @(state_r) begin
      case ({state_r})
        IDLE:     _stateascii_r  = "idle   ";
        SEND:     _stateascii_r  = "send   ";
        WAIT1:    _stateascii_r  = "wait1  ";
        UPDATE1:  _stateascii_r  = "update1";
        WAIT2:    _stateascii_r  = "wait2  ";
        UPDATE2:  _stateascii_r  = "update2";
        default:  _stateascii_r  = "%Error ";
      endcase
   end


endmodule

