module top_module(
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input [7:0] input1,
    input [7:0] input2,
    input sel,
    input control,
    output reg [7:0] out_result
);// 4-to-1 multiplexer
wire [7:0] mux_out;
assign mux_out = (sel == 0) ? input1 : input2;

// 4-bit shift register
reg [3:0] shift_reg;
always @(posedge clk or negedge areset) begin
    if (!areset) begin
        shift_reg <= 4'b0;
    end else if (load) begin
        shift_reg <= mux_out;
    end else if (ena) begin
        if (control == 0) begin
            // left shift
            shift_reg <= {shift_reg[2:0], 1'b0};
        end else begin
            // right shift
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end
end

// functional module
always @(*) begin
    if (control == 0) begin
        // addition
        out_result = shift_reg + input1;
    end else begin
        // subtraction
        out_result = shift_reg - input1;
    end
end

endmodule

