  always @(*) 
  if (WE) ADDR_LATCH <= ADDR_COUNTER; 
  assign #10 DATA_OUT = RAM_RE ? LB_RAM[ADDR_LATCH] : 12'bzzzzzzzzzzzz; 
  always @(posedge RAM_WE) 
  LB_RAM[ADDR_LATCH] <= DATA_IN; 
 endmodule

