module gray_code_counter (
    input clk,
    input sreset,
    input en,
    output reg [2:0] count);

    function [2:0] gray_encode(input [2:0] binary);
        gray_encode = binary ^ (binary >> 1);
    endfunction

    always @(posedge clk) begin
        if (sreset) begin
            count <= 3'b000;
        end else if (en) begin
            count <= gray_encode(count + 1);
        end
    end
endmodule

module mux4to1_16bit (
    input [1:0] sel,
    input [15:0] in0,
    input [15:0] in1,
    input [15:0] in2,
    input [15:0] in3,
    output [15:0] out
);

    reg [15:0] mux_out;  // Multiplexer output register

    always @(*) begin
        case (sel)
            2'b00: mux_out = in0;
            2'b01: mux_out = in1;
            2'b10: mux_out = in2;
            2'b11: mux_out = in3;
            default: mux_out = 16'b0;  // Default case (should not occur)
        endcase
    end

    assign out = mux_out;

endmodule

