module top_module(
    input Clk,
    input Reset,
    input [7:0] Divider1,
    input [7:0] Divider2,
    output reg LED1,
    output reg LED2
);reg [7:0] counter1;
reg [7:0] counter2;

always @(posedge Clk or posedge Reset) begin
    if (Reset) begin
        counter1 <= 8'b0;
        counter2 <= 8'b0;
        LED1 <= 1'b0;
        LED2 <= 1'b0;
    end else begin
        counter1 <= counter1 + 1;
        counter2 <= counter2 + 1;
        if (counter1 == Divider1 - 1) begin
            LED1 <= ~LED1;
            counter1 <= 8'b0;
        end
        if (counter2 == Divider2 - 1) begin
            LED2 <= ~LED2;
            counter2 <= 8'b0;
        end
    end
end

endmodule

