  if (sending && timeout == 0) begin 
  timeout <= 100 - 1; 
  if (sendbuf[8:0] == 9'b000000001) 
  sending <= 0; 
  else 
  sendbuf <= {1'b0, sendbuf[9:1]}; 
  end 
  end 
