module traffic_light (
        input clk,
        input areset,
        input timer_done,
        output reg [1:0] light);parameter Red=2'b00, Green=2'b01, Yellow=2'b10;
	reg [1:0] state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= Red;
		else begin
			case (state)
				Red: state <= timer_done ? Green : Red;
				Green: state <= timer_done ? Yellow : Green;
				Yellow: state <= timer_done ? Red : Yellow;
			endcase
		end
	end

	assign light = state;

endmodule

