  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter M=2'b00, N=2'b01, O=2'b10, P=2'b11;

    always_comb begin
		case (state)
			M: next_state = in ? O : N;
			N: next_state = in ? P : O;
			O: next_state = in ? M : P;
			P: next_state = in ? N : M;
		endcase
    end

    always_comb begin
		case (state)
			M: out = 0;
			N: out = 1;
			O: out = 1;
			P: out = 0;
		endcase
    end

endmodule

