module johnson_counter(
    input clk,
    input reset,
    output reg [2:0] count_out
);
    always @(posedge clk or posedge reset) begin
        if (reset)
            count_out <= 3'b000;
        else
            count_out <= {~count_out[2], count_out[2:1]};
    end
endmodule

